### Подключение к Redis



Фреймворк ASP.NET Core предоставляет встроенные инструменты для работы с Redis. Так, создадим проект ASP.NET Core. Для работы с Redis добавим в проект Nuget-пакет **Microsoft.Extensions.Caching.StackExchangeRedis**



Для рассмотрения механизма кэширования возьмем простенькую задачу: закэшируем некоторую информацию о пользователе, которая может не изменяться в течение более долгого периода времени, и поэтому эту информацию мы можем кэшировать, чтобы в будущем избежать лишних обращений к бд.



Для простоты и демонстрации в качестве базы данных будем использовать базу данных SQLite, с которой будем работать через Entity Framework. Поэтому добавим в проект через Nuget пакет **Microsoft.EntityFrameworkCore.Sqlite**.




Далее определим в файле **Program.cs** следующий код приложения:



```c#

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Distributed;
using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);

// внедрение зависимости Entity Framework
builder.Services.AddDbContext<ApplicationContext>(options => options.UseSqlite("Data Source=usercacheapp.db"));
// внедрение зависимости UserService
builder.Services.AddTransient<UserService>();
// добавление кэширования
builder.Services.AddStackExchangeRedisCache(options => {
    options.Configuration = "localhost";
    options.InstanceName = "local";
});
var app = builder.Build();

app.MapGet("/user/{id}", async (int id, UserService userService) =>
{
    User? user = await userService.GetUser(id);
    if (user != null) return $"User {user.Name}  Id={user.Id}  Age={user.Age}";
    return "User not found";
});
app.MapGet("/", () => "Hello World!");

app.Run();


public class User
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public int Age { get; set; }
}
public class ApplicationContext : DbContext
{
    public DbSet<User> Users { get; set; } = null!;
    public ApplicationContext(DbContextOptions<ApplicationContext> options) : base(options) => 
        Database.EnsureCreated();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // инициализация БД начальными данными
        modelBuilder.Entity<User>().HasData(
                new User { Id = 1, Name = "Tom", Age = 23 },
                new User { Id = 2, Name = "Alice", Age = 26 },
                new User { Id = 3, Name = "Sam", Age = 28 }
        );
    }
}
public class UserService
{
    ApplicationContext db;
    IDistributedCache cache;
    public UserService(ApplicationContext context, IDistributedCache distributedCache)
    {
        db = context;
        cache = distributedCache;
    }
    public async Task<User?> GetUser(int id)
    {
        User? user = null;
        // пытаемся получить данные из кэша по id
        var userString = await cache.GetStringAsync(id.ToString());
        //десериализируем из строки в объект User
        if (userString != null) user = JsonSerializer.Deserialize<User>(userString);

        // если данные не найдены в кэше
        if (user == null)
        {
            // обращаемся к базе данных
            user = await db.Users.FindAsync(id);
            // если пользователь найден, то добавляем в кэш
            if (user != null)
            {
                Console.WriteLine($"{user.Name} извлечен из базы данных");
                // сериализуем данные в строку в формате json
                userString = JsonSerializer.Serialize(user);
                // сохраняем строковое представление объекта в формате json в кэш на 2 минуты
                await cache.SetStringAsync(user.Id.ToString(), userString, new DistributedCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(2)
                });
            }
        }
        else
        {
            Console.WriteLine($"{user.Name} извлечен из кэша");
        }
        return user;
    }
}
```






Вкратце рассмотрим код. Прежде всего определяем класс **User**, который будет описывать используемые данные и объекты которого будут храниться в базе данных SQLite:



```c#

public class User
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public int Age { get; set; }
}
```



Для взаимодействия с базой данных применяется класс контекста данных **ApplicationContext**:



```c#

public class ApplicationContext : DbContext
{
    public DbSet<User> Users { get; set; } = null!;
    public ApplicationContext(DbContextOptions<ApplicationContext> options) : base(options) => 
        Database.EnsureCreated();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // инициализация БД начальными данными
        modelBuilder.Entity<User>().HasData(
                new User { Id = 1, Name = "Tom", Age = 23 },
                new User { Id = 2, Name = "Alice", Age = 26 },
                new User { Id = 3, Name = "Sam", Age = 28 }
        );
    }
}
```



Для тестирования в методе `OnModelCreating()` инициализируем базу данных тремя объектами.



Для взаимодействия с контекстом данных и кэшем определен класс **UserService**:



```c#

public class UserService
{
    ApplicationContext db;
    IDistributedCache cache;
    public UserService(ApplicationContext context, IDistributedCache distributedCache)
    {
        db = context;
        cache = distributedCache;
    }
    public async Task<User?> GetUser(int id)
    {
        User? user = null;
        // пытаемся получить данные из кэша по id
        var userString = await cache.GetStringAsync(id.ToString());
        //десериализируем из строки в объект User
        if (userString != null) user = JsonSerializer.Deserialize<User>(userString);

        // если данные не найдены в кэше
        if (user == null)
        {
            // обращаемся к базе данных
            user = await db.Users.FindAsync(id);
            // если пользователь найден, то добавляем в кэш
            if (user != null)
            {
                Console.WriteLine($"{user.Name} извлечен из базы данных");
                // сериализуем данные в строку в формате json
                userString = JsonSerializer.Serialize(user);
                // сохраняем строковое представление объекта в формате json в кэш на 2 минуты
                await cache.SetStringAsync(user.Id.ToString(), userString, new DistributedCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(2)
                });
            }
        }
        else
        {
            Console.WriteLine($"{user.Name} извлечен из кэша");
        }
        return user;
    }
}
```



Данный сервис через встроенный механизм внедрения зависимостей будет получать контекст данных - объект ApplicationContext и использовать его для взаимодействия с бд.



Также через механизм внедрения зависимостей сервис в конструкторе получает сервис IDistributedCache, через который приложение будет взаимодействовать с сервером Redis.



В методе `GetUser()` сервис UserService получает объект User по id. При получении объекта вначале пытаемся найти этот объект в кэше. Поскольку IDistributedCache позволяет сохранять данные только в виде массива байтов и строки, то в данном случае мы будем хранить в кэше объект User в формате json в виде строки. И вначале получаем по id строковое представление объекта из кэша:



```c#
var userString = await cache.GetStringAsync(id.ToString());
```



Здесь ключами элементов в кэше являются значения id. Если ключ в кэше был найден, то десериализуем полученное значение с помощью метода `JsonSerializer.Deserialize()`



```c#
if (userString != null) user = JsonSerializer.Deserialize<User>(userString);
```



Если в кэше не оказалось объекта, то извлекаем его и бд, сериализуем его в строку и затем добавляем в кэш на 2 минуты:



```c#

user = await db.Users.FindAsync(id);
if (user != null)
{
    Console.WriteLine($"{user.Name} извлечен из базы данных");
    userString = JsonSerializer.Serialize(user);
    await cache.SetStringAsync(user.Id.ToString(), userString, new DistributedCacheEntryOptions
    {
        AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(2)
    });
}
```



Для добавления в кэш в метод `SetStringAsync()` передаем ключ объекта - его Id, затем передаем само кэшируемое значение - сериализованный объект User. И далее устанавливаем опции кэширования с помощью объекта DistributedCacheEntryOptions. В частности, с помощью свойства `AbsoluteExpirationRelativeToNow` задаем время кэширования относительно текущего момента в виде 2 минут.



#### Регистрация Redis



Чтобы получить сервис IDistributedCache, который взаимодействует с локальным сервером Redis, необходимо добавить сервисы кэширования с помощью вызова:



```c#

builder.Services.AddStackExchangeRedisCache(options => {
    options.Configuration = "localhost";
    options.InstanceName = "local";
});
```



Метод `AddStackExchangeRedisCache()` в качестве параметра принимает делегат `Action `. Его параметр - объект **RedisCacheOptions** позволяет установить настройки подключения с помощью своих свойств:





- Configuration : конфигурация подключения к серверу Redis. Для подключения к локально запущенному серверу можно указать, как в примере выше, строку "localhost". Для подключения к внешним серверам Redis на других хостах указываются адрес хоста и порт, соответственно точную конфигурацию надо узнавать у хостера.

- InstanceName : имя экземпляра Redis. Для локального экземпляра можно указать "local". Это имя будет использоваться в качестве префикса для сохраняемых в кэше данных.



И для тестирования определим конечную точку, где клиент передает id через параметр маршрута, и сервис UserService по этому id пытается найти в базе данных и кэше нужный объект User:



```c#

app.MapGet("/user/{id}", async (int id, UserService userService) =>
{
    User? user = await userService.GetUser(id);
    if (user != null) return $"User {user.Name}  Id={user.Id}  Age={user.Age}";
    return "User not found";
});
```



Запустим сервер Redis и затем наше приложение и обратимся по адресу `https://localhost:xxxx/user/1` (то есть для получения объекта User с id=1). В итоге при первом обращении к приложению данные будут извлекаться из базы данных и сохраняться в кэш. При всех последующих обращениях в пределах времени кэширования (в данном случае в течение 5 минут) данные будут извлекаться из кэша:



![imemorycache и кэширование в приложении asp.net core на c#](/uploads/course-lectures/409873f31b20de855332a91ee5781c70669917c6.png)



А в кэше Redis мы можем увидеть сохраненный объект. Для этого нам надо в консоли обратиться к redis-cli с помощью команды



```consoletext
redis-cli
```

 

Затем получить все ключи с помощью команды



```consoletext
keys *
```

 

Поскольку в настройках конфигурации подключения Redis в коде C# в качестве имени экземпляра задана строка "local", а ключ сохраняенного объекта - это его id, то есть число id, то в самом Redis сохраненный объект будет храниться по ключу "local1". И для получения данных по записи с этим ключом выполним команду



```consoletext
hgetall local1
```

 

То есть команде `hgetall` передается ключ записи



![получение из сервера redis сохраненной записи по ключу в приложении на asp.net core и c#](/uploads/course-lectures/55752cca5e210805dddad13b1bd56cea1bcf4fcb.png)



### DistributedCacheEntryOptions



Для установки параметров кэширования в метод **Set/SetAsync/SetString/SetStringAsync** в качестве третьего параметра можно передать объект **DistributedCacheEntryOptions**, который устанавливает настройки кэширования объекта с помощью ряда свойств:





- AbsoluteExpiration : возвращает или задает абсолютную дату окончания кэширования

- AbsoluteExpirationRelativeToNow : возвращает или задает абсолютную дату окончания кэширования относительно текущего момента

- SlidingExpiration : возвращает или задает время, в течение которого запись кэша может быть неактивной (то есть к ней нет обращений), прежде чем она будет удалена. 
Это значение не увеличивает время кэширования записи - оно по прежнему остается в рамках абсолютной даты кэширования (если она задана).

Компрессия или сжатие ответа представляет один из инструментов, которые позволяют уменьшить объем отправляемых клиенту данных без потери самих данных.



Для компрессии ответа в рамках ASP.NET Core мы можем использовать либо внутренние средства конкретного веб-сервера: модуль динамического сжатия (Dynamic Compression module) в IIS, модуль mod_deflate в Apache или инструменты компрессии в Nginx. Однако эти инструменты не всегда бывают доступны, особенно когда приложение напрямую хостится в рамках таких веб-серверов как HTTP.sys или Kestrel. И в этом случае мы можем воспользоваться специальным компонентом middleware - **Microsoft.AspNetCore.ResponseCompression**. Рассмотрим, как использовать этот компонент.



Для этого возьмем проект ASP.NET Core и в файле **Program.cs** определим простейшее приложение, которое отправляет длинную строку и применяет кэширование:



```c#

var builder = WebApplication.CreateBuilder(args);

// добавляем сервисы сжатия
builder.Services.AddResponseCompression(options => options.EnableForHttps = true);

var app = builder.Build();

// подключаем сжатие
app.UseResponseCompression();

app.MapGet("/", () => "Lorem Ipsum is simply dummy text of the printing and typesetting industry...exact original form, accompanied by English versions from the 1914 translation by H. Rackham.");

app.Run();
```



Вначале нам надо подключить соответствующий сервис:



```c#
builder.Services.AddResponseCompression(options=>options.EnableForHttps = true);
```



Следует учитывать, что для протокола HTTPS по умолчанию отключено сжатие, поэтому в вызове данного метода подключается сжатие и для HTTPS. Однако если HTTPS не используется, то можно сократить вызов метода:



```c#
builder.Services.AddResponseCompression();
```



Затем в методе Configure задействуем middleware сжатия:



```c#
app.UseResponseCompression();
```



Запустим проект на выполнение:



![компрессия и сжатие ответа в приложении asp.net core на c#](/uploads/course-lectures/a6d213d8a446bd235baee7064ae7ea9f6498b162.png)



На уровне протокола HTTP это выражается также в установлении заголовка **content-encoding**, который сервер вместе с ответом посылает клиенту. По умолчанию этот заголовок имеет значение `content-encoding: br`, который говорит о том, что используется сжатие в формат `Brotli`



Теперь уберем из метода Configure применение компрессии - удалим или закомментируем следующую строку:



```c#
app.UseResponseCompression();
```



В этом случае мы получим немного другие значения.



![компрессия в веб-приложении asp.net core на c# и метод useresponsecompression](/uploads/course-lectures/2062429a6d5c99bcafc7fa61b87e67b1fe2155b2.png)



При использовании компрессии надо учитывать обратную сторону компрессии - уменьшение производительности: затраты на компрессию могут превосходить выгоду от уменьшения объема данных. Поэтому, для небольших объемов (меньше 1 кб) не очень рационально применение компрессии.



### Установка заголовков типа ответа



При использования компрессии при отправке ответа нам обязательно надо установить MIME-тип отправляемых данных:



Так, в примере выше при отправке ответа в конечной точке



```c#
app.MapGet("/", () => "Lorem Ipsum ...
```



Заголовок типа ответа устанавливался автоматически. При использовании ASP.NET MVC или Razor Pages также необязательно указывать MIME-тип ответа. Однако не все middleware и компоненты в конвейере ASP.NET Core автоматически устанавливают заголовки. Например, при обработке запроса с помощью метода `Run` заголовки не устанавливаются, и их надо устанавливать вручную:



```c#

var builder = WebApplication.CreateBuilder(args);

// добавляем сервисы сжатия
builder.Services.AddResponseCompression(options => options.EnableForHttps = true);

var app = builder.Build();

// подключаем сжатие
app.UseResponseCompression();

app.Run(async (context) =>
{
    // устанавливаем MIME-тип ответа
    context.Response.ContentType = "text/plain"; // отправляем простой текст
    await context.Response.WriteAsync("Lorem Ipsum is simply dummy text of the printing and typesetting industry...exact original form, accompanied by English versions from the 1914 translation by H. Rackham.");
});

app.Run();
```



То есть в данном случае отправляем простой текст, поэтому MIME-тип `text/plain`. На данный момент middleware компрессии поддерживает следующие MIME-типы:





- text/plain

- text/css

- application/javascript

- text/html

- application/xml

- text/xml

- application/json

- text/json






### Настройка сжатия



Метод `AddResponseCompression()` принимает делегат, который принимает объект **ResponseCompressionOptions**. Через свойства этого объекта можно установить параметры кэширования:





- EnableForHttps устанавливает доступность сжатия для запросов по https

- Providers представляет коллекцию провайдеров компрессии, которые применяются для сжатия ответа. Каждый провайлер представлен типом ICompressionProvider. Для добавления провайдера в эту коллекцию используется метод Add() , а для удаления - метод Remove() .

- MimeTypes определяет Mime-типы ответа, к которым применяется сжатие

- ExcludedMimeTypes устанавливает Mime-типы ответа, к которым НЕ применяется сжатие



Например, исключим из сжатия простой текст:



```c#

builder.Services.AddResponseCompression(options =>
{
    options.EnableForHttps = true;
    // исключаем из сжатия простой текст
    options.ExcludedMimeTypes = new[] { "text/plain" };
});
```




### Провайдеры компрессии



Механизм компрессии на уровне протокола HTTP сосредоточен вокруг двух заголовков. Вначале клиент в запросе посылает заголовок **Accept-Encoding**, в котором уведомляет сервер, какие форматы сжатия он поддерживает. Сервер, получив запрос, использует этот заголовок для выбора формата сжатия и затем посылает вместе с ответом клиенту заголовок **Сontent-Encoding**, в котором указывает использованный формат сжатия. Если клиент поддерживает сжатие в формат Brotli, то по умолчанию используется этот формат. Если клиент не поддерживает данный формат, то используется сжатия gzip.



#### Brotli Compression Provider



В примере выше по умолчанию использовалось сжатие в формат Brotli с помощью класса **BrotliCompressionProvider**. Он имеет свойство **Level**, которое устанавливает уровни сжатия и может принимать следующие значения:





- CompressionLevel.Fastest : сжатие должно происходить как можно быстрее, даже если оно будет неоптимальным в плане уменьшения объема данных.

- CompressionLevel.NoCompression : сжатие не применяется

- CompressionLevel.Optimal : данные должны быть максимально сжаты, даже если для этого потребуется больше времени



Для изменения уровня компрессии можно применить метод `Configure()` объекта ServiceCollection:



```c#

using Microsoft.AspNetCore.ResponseCompression;
using System.IO.Compression;

var builder = WebApplication.CreateBuilder(args);

// добавляем сервисы сжатия
builder.Services.AddResponseCompression(options =>  options.EnableForHttps = true);
// устанавливаем уровень сжатия
builder.Services.Configure<BrotliCompressionProviderOptions>(options => options.Level = CompressionLevel.Optimal);

var app = builder.Build();

// подключаем сжатие
app.UseResponseCompression();

app.MapGet("/", () => "Lorem Ipsum is simply dummy text of the printing and typesetting industry...exact original form, accompanied by English versions from the 1914 translation by H. Rackham.");

app.Run();
```




#### GzipCompressionProvider



Также мы можем использовать сжатие gzip, а если точнее класс **GzipCompressionProvider**, который обеспечивает компрессию gzip. Он используется, если клиент не поддерживает сжатие в формат Brotli. Для его использования его надо добавить в коллекцию провайдеров сжатия:



```c#

using Microsoft.AspNetCore.ResponseCompression;
using System.IO.Compression;

var builder = WebApplication.CreateBuilder(args);

// добавляем сервисы сжатия
builder.Services.AddResponseCompression(options =>
{
    options.EnableForHttps = true;
    // добавляем провайдер gzip-сжатия
    options.Providers.Add(new GzipCompressionProvider(new GzipCompressionProviderOptions()));
});

var app = builder.Build();

// подключаем сжатие
app.UseResponseCompression();

app.MapGet("/", () => "Lorem Ipsum is simply dummy text of the printing and typesetting industry...exact original form, accompanied by English versions from the 1914 translation by H. Rackham.");

app.Run();
```



В качестве параметра конструктор GzipCompressionProvider принимает объект `GzipCompressionProviderOptions`, который устанавливает настройки gzip-сжатия. Этот объект также имеет свойство **Level**, которое принимает те же значения, что и BrotliCompressionProvider:



```c#

builder.Services.Configure<GzipCompressionProviderOptions>(options => options.Level = CompressionLevel.Optimal);
```



В качестве альтернативы можно добавлять провайдеры типизацией метода `Add()`:



```c#
options.Providers.Add<GzipCompressionProvider>();
```



#### Создание своих провайдеров



При необходимости мы можем создавать и применять свои провайдеры сжатия. Например, используем сжатие Deflate, и для этого изменим код программы следующим образом:



```c#

using Microsoft.AspNetCore.ResponseCompression;
using System.IO.Compression;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddResponseCompression(options =>
{
    options.EnableForHttps = true;
    // добавляем провайдер сжатия DeflateCompressionProvider
    options.Providers.Add(new DeflateCompressionProvider());
});
var app = builder.Build();

// подключаем сжатие
app.UseResponseCompression();

app.MapGet("/", () => "Lorem Ipsum is simply dummy text of the printing and typesetting industry...exact original form, accompanied by English versions from the 1914 translation by H. Rackham.");

app.Run();

public class DeflateCompressionProvider : ICompressionProvider
{
    public string EncodingName => "deflate";
    public bool SupportsFlush => true;
    public Stream CreateStream(Stream outputStream)
    {
        return new DeflateStream(outputStream, CompressionLevel.Optimal);
    }
}
```



Для создания провайдера реализуем интерфейс **ICompressionProvider**, в котором есть два свойства SupportsFlush и EncodingName и метод CreateStream.



Свойство **EncodingName** указывает на формат сжатия, который поддерживает клиент. Данный формат содержится в заголовке `Accept-Encoding` в запросе к серверу, наподобие:



```javascript

Accept-Encoding: gzip, deflate, sdch, br
```



То есть данный провайдер будет срабатывать, если клиент прислал в запросе в заголовке Accept-Encoding значение **deflate**.



Свойство **SupportsFlush** указывает, поддерживается ли сброс записи в поток.



Метод **CreateStream()** возвращает сам поток ответа после сжатия или фактически обертка над изначальным потоком ответа, который передается в качестве параметра в метод. Для сжатия применяется встроенный класс **DeflateStream()**.





Стоит отметить, что если мы добавляем кастомный провайдер компрессии, то в случае если тип сжатия не поддерживается клиентом, то лучше также добавлять и провайдеры по умолчанию BrotliCompressionProvider и GzipCompressionProvider:



```c#

builder.Services.AddResponseCompression(options =>
{
    options.EnableForHttps = true;
    // добавляем провайдер сжатия DeflateCompressionProvider
    options.Providers.Add<DeflateCompressionProvider>();
    options.Providers.Add<GzipCompressionProvider>();
    options.Providers.Add<BrotliCompressionProvider>();
});
```



В итоге при получении запроса провайдеры будут перебираться в том порядке, в котором они добавлены. И первый попавшийся провайдер, формат сжатия которого поддерживается клиентом, и будет выбран для осуществления компрессии.

Кроме кэширования результатов действий контроллера для оптимизации работы приложения можно применять кэширование статического контекта. В данном случае статический контент - это файлы изображений, скрипты javascript, файлы стилей css, какие-то другие файлы, например, аудио-файлы, используемые на странице. Как правило, подобные файлы в проекте размещаются в папке **wwwroot**.

Для кэширования статических файлов при их отправке следует установить соответствующие заголовки. Для этого StaticFilesMiddleware передается объект **StaticFileOptions**, у которого устанавливается свойство **OnPrepareResponse : ```c#
app.UseStaticFiles(new StaticFileOptions()
{
	OnPrepareResponse = ctx =>
	{
		ctx.Context.Response.Headers.Add("Cache-Control", "public,max-age=600");
	}
});
``` Свойство OnPrepareResponse представлят делегат Action - некоторое действие, которое в качестве параметра принимает объект StaticFileResponseContext**. Через этот объект можно установить заголовки ответа, который будут посылаться вместе со статическими файлами. В частности, в данном случае устанавливается заголовок "Cache-Control", который задает параметры кэширования. Так, значение "public" указывает, что файл будет кэшироваться как в кэше браузера, так и на промежуточных прокси-серверах.

А параметр `max-age` задает время кэширования в секундах. Так, в данном случае файл кэшируется 10 минут (600 секунд).

Для теста определим небольшой проект ASP.NET Core, в котором в папке **wwwroot** будут находиться три статических файла: `index.html`, `app.js` и `styles.css`

![кэширование статических файлов в приложении asp.net core на c# и класс staticfileresponsecontext](/uploads/course-lectures/962e8e93ef7a03df657141fd9c67bf2db9b88613.png)

Допустим, на странице **index.html** будет какое-то простенькое содержимое и подключение файлов `app.js` и `styles.css`:

```xml
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <title>enoobis.ru</title>
    <link rel="stylesheet" href="styles.css" />
</head>
<body>
    <h2>Hello enoobis.ru!</h2>
    <script src="app.js"></script>
</body>
</html>
```

В файле **Program.cs** определим кэщирование статических файлов:

```c#
var builder = WebApplication.CreateBuilder(args);

var app = builder.Build();

app.UseDefaultFiles();
app.UseStaticFiles(new StaticFileOptions()
{
    OnPrepareResponse = ctx =>
    {
        ctx.Context.Response.Headers.Add("Cache-Control", "public,max-age=600");
    }
});

app.Run();
```

При отправке запроса браузер получит вместе с файлами заголовки ответа, которые устанавливают параметры кэширования:

![кэширование статических файлов в приложении asp.net core на c#](/uploads/course-lectures/a8229ac77e7aa205030d6a8e3da35b77954d590b.png)

При повторной отправке запроса браузер будет доставать файлы из кэша:

![кэширование статических файлов в приложении asp.net core на c#](/uploads/course-lectures/3c9a317a4ccce7265a1a445136c3c06f562daf5e.png)

### Версии файлов

У кэширования есть недостаток: если мы изменим, например, содержимое файла css или javascript, то при повторном обращении к приложению браузер продолжит извлекать нужные файлы из кэша (если срок кэширования не истек). И таким образом, мы будем использовать старые версии файлов.

Для решения этой проблемы можно добавлять к статическим файлам версию и при каждом изменении файла соответственно менять версию файла:

```xml
<link rel="stylesheet" href="/css/site.css?v=123" />
<script src="app.js?v=123"></script>
```

ASP.NET позволяет кэшировать ответ приложения, и для этого применяет сервис **IOutputCacheStore** и middleware **OutputCacheMiddleware**. Рассмотрим, как их использовать в приложении.



Для кэширования ответа приложения нам надо прежде всего сконфигурировать приложения. Для этого следует выполнить два шага. Прежде всего, добавить в коллекцию сервисов приложения все необходимые сервисы с помощью метода **AddOutputCache()**



```c#

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddOutputCache();
```



Во-вторых, надо добить в конвейер приложения middleware `OutputCacheMiddleware` с помощью метода **UseOutputCache()**:



```c#

var app = builder.Build();
app.UseOutputCache();
```



После этого можно применять кэширование. Рассмотрим простейший пример:



```c#

var users = new List<string> { "Tom", "Bob", "Sam" }; 

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOutputCache();  // добавляем сервисы

var app = builder.Build();

app.UseOutputCache();       // добавляем OutputCacheMiddleware

app.MapGet("/", async () =>
{
    await Task.Delay(5000);     // имитация долгой обработки
    return users;
}).CacheOutput();   // применяем кэширование к результату обработки метода app.MapGet("/")

app.Run();
```



Здесь при обращении по адресу "/" приложение будет отдавать список users.



```c#

app.MapGet("/", async () =>
{
    await Task.Delay(5000);     // имитация долгой обработки
    return users;
}).CacheOutput();
```



Для упрощения задачи здесь данные определены локально в виде списка, но в реальности это могут быть данные, которые приходят из базы данных, с другого сервера с помощью дополнительного сетевого запроса и т.д. А для искусственной имитации долгой обработки запроса я добавил задержку в 5 секунд. И чтобы при всех последующих обращениях приложение не обрабатывало повторно запрос, применяем кэширование. Для этого к методу `app.MapGet` по цепочке добавляем вызов метода **CacheOutput()**.



### Применение кэширования



Чтобы применить кэширование к результату определенного метода, можно использовать два способа:





- Вызов метода CacheOutput() , которые определен как метод расширения для типа IEndpointConventionBuilder . То есть, как в примере выше, мы можем его вызвать по цепочке после метода Map/MapGet/MapPost/MapPut/MapDelete/MapPatch и т.д.: ```c#

app.MapGet("/", () => users).CacheOutput();  // применяем кэширование
```


- Применение атрибута [CacheOutput] к обработчику конечной точки: ```c#

using Microsoft.AspNetCore.OutputCaching;   // для атрибута [OutputCache]
.....................
app.MapGet("/", [OutputCache]() => users);
```






### Ограничения кэширования



Одна из перегруженных версий метода `AddOutputCache` принимает делегат Action , параметр которого - объект **OutputCacheOptions** с помощью свойств позволяет настроить предельные значения кэширования:

 



- SizeLimit : максимальный размер кэш-хранилища. При достижении этого предела новые ответы не будут кэшироваться до тех пор, пока старые записи не будут удалены. Значение по умолчанию — 100 МБ

- MaximumBodySize : максимальный размер отдельного объекта, помещаемого в кэш. Если ответ превышает этот предел, он не будет кэшироваться. Значение по умолчанию — 64 МБ

- DefaultExpirationTimeSpan : срок действия, который применяется, если он не указан политикой. Значение по умолчанию — 60 секунд



Пример применения:



```c#

using Microsoft.AspNetCore.OutputCaching;

var users = new List<string> { "Tom", "Bob", "Sam" }; 

var builder = WebApplication.CreateBuilder(args);

// переустанавливаем ограничения кэширования
builder.Services.AddOutputCache(o=>
{
    o.MaximumBodySize = 4 * 1024 * 1024;    // 4 Мб
    o.SizeLimit = 64 * 1024 * 1024;    // 64 Мб
    o.DefaultExpirationTimeSpan = TimeSpan.FromMinutes(2);  // 2 минуты
});

var app = builder.Build();

app.UseOutputCache();
app.MapGet("/", () => users).CacheOutput();   

app.Run();
```



### Настройка кэширования



Метод `CacheOutput()` имеет ряд перегрузок, которые позволяют настроить кэширование. Рассмотрим одну из них:



```c#

CacheOutput (Action<Microsoft.AspNetCore.OutputCaching.OutputCachePolicyBuilder> policy)
```



В данную перегрузку в метод передается делегат, который с помощью методов параметра **OutputCachePolicyBuilder** настраивает опции кэширования. В частности, мы можем использовать следующие методы OutputCachePolicyBuilder:





- Expire (TimeSpan expiration) : устанавливает время кэширования в виде объекта TimeSpan. После истечения этого времени кэш сбрасывается

- SetVaryByHeader (string[] headerNames) : для каждого набора заголовков, переданных в метод, устанавливает свою версию кэша

- SetVaryByHost (bool enabled) : если в метод передается значение true , то для каждого хоста устанавливается своя версия кэша.

- SetVaryByQuery (string[] queryKeys) : устанавливает свою версию кэша для набора параметров строки запроса, которые передаются в метод

- SetVaryByRouteValue (string[] routeValueNames) : : устанавливает свою версию кэша для набора параметров маршрута, которые передаются в метод



Так, в первом примере из статьи кэш сохранялся на протяжении всего приложения, что не очень хорошо, поскольку данные могут измениться. Изменим код приложения, установив время кэширования:



```c#

var users = new List<string> { "Tom", "Bob", "Sam" }; 

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOutputCache();  // добавляем сервисы

var app = builder.Build();

app.UseOutputCache();       // добавляем OutputCacheMiddleware

// добавляем в список строку, которая передается через параметр маршрута name
app.MapGet("/add/{name}", (string name) => 
{
    users.Add(name);
    return $"{name} has been added";
});

app.MapGet("/", () => users)
    .CacheOutput(t => t.Expire(TimeSpan.FromMinutes(2))); // время кэширования 2 минуты

app.Run();
```



Для тестирования также определена еще одна конечная точка, которая обрабатывает запрос по путь "/add/{name}" - через параметр name передается строка, которая добавляется в список users:



```c#

app.MapGet("/add/{name}", (string name) => 
{
    users.Add(name);
    return $"{name} has been added";
});
```



Также устанавливаем для кэша время действия в 2 минуты



```c#

app.MapGet("/", () => users)
    .CacheOutput(t => t.Expire(TimeSpan.FromMinutes(2)));
```



Запустим приложение и сначала обратимся по пути "/", чтобы получить и закэшировать список:



![установка кэширования ответа и метод outputcache в asp.net core в c#](/uploads/course-lectures/ed39846dcbd1df1da4af0a6d88f11b3d5b23998f.png)



И затем, пока идет время кэширования, обратимся по пути "add/Alice", добавив строку "Alice" в список:



![установка времени кэширования ответа и метод outputcache в asp.net core в c#](/uploads/course-lectures/ca1c8adfa181a93bb62ebe77d05f39d1b9b43ae0.png)



Если время кэширования НЕ истекло, то при повторном обращении по пути "/" мы получим ранее закешированный список без добавленного элемента.



![установка кэширования ответа и метод outputcache в asp.net core в c#](/uploads/course-lectures/ed39846dcbd1df1da4af0a6d88f11b3d5b23998f.png)



После завершения времени кэширования, которое в примере выше равно 2 минутам, мы получим список с уже добавленным элементом, и этот обновленный список также будет закэшировна на 2 минуты



![установка времени кэширования и метод outputcache в asp.net core в c#](/uploads/course-lectures/d8a71060ee524a065f758db4a8755f1e6fd161cc.png)



Подобным образом можно устанавливать и другие параметры кэширования. Например, разграничим кэш для разных значений параметра "username" в строке запроса:



```c#

app.MapGet("/", () => users)
    .CacheOutput(t => t.SetVaryByQuery("username"));
```



#### Настройка кэширования с помощью атрибута OutputCache



Аналогичную настройку кэширования можно выполнить с помощью свойств атрибута **[OutputCache]**:





- int Duration : устанавливает время кэширования в секундах

- string[]? VaryByHeaderNames : устанавливает набор заголовоков, для которых создается кэш

- string[]? VaryByQueryKeys : устанавливает набор параметров строки запроса, для которых создается кэш

- string[]? VaryByRouteValueNames : устанавливает набор параметров маршрута, для которых создается кэш



Например, установки кэширования на 2 минуты:



```c#
app.MapGet("/", [OutputCache(Duration = 120)] () => users);
```



### Метка кэширования и сброс кэша



Метод **Tag()** типа OutputCachePolicyBuilder позволяет задать для закешированного результата определенную метку:



```c#

app.MapGet("/", () => users)
    .CacheOutput(t=>
    {
        t.Expire(TimeSpan.FromMinutes(2));  // время кэширования - 2 минуты
        t.Tag("users");     // метка "users"
    });
```



С помощью метки мы сможем удалить кэш в произвольный момент времени:



```c#

using Microsoft.AspNetCore.OutputCaching;

var users = new List<string> { "Tom", "Bob", "Sam" }; 

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOutputCache();

var app = builder.Build();

app.UseOutputCache();

app.MapGet("/add/{name}", (string name) =>
{
    users.Add(name);
    return $"{name} has been added";
});
app.MapGet("/", () => users)
    .CacheOutput(t=>
    {
        t.Expire(TimeSpan.FromMinutes(2));
        t.Tag("users");
    });   

// сбрасываем кэш
app.MapGet("/reset", async (IOutputCacheStore cache) =>
{
    // удаляем кэшированный объект с меткой "users"
    await cache.EvictByTagAsync("users", new CancellationToken());
    return "Cache Reset";
});

app.Run();
```



Для удаления из кэша объекта с меткой "users" получаем из коллекции сервисов сервис **IOutputCacheStore** и у него вызываем метод **EvictByTagAsync()**. Этот метод в качестве первого параметра принимает метку объекта в кэше, а в качестве второго токен отмены CancellationToken:



```c#

app.MapGet("/reset", async (IOutputCacheStore cache) =>
{
    // удаляем кэшированный объект с меткой "users"
    await cache.EvictByTagAsync("users", new CancellationToken());
    return "Cache Reset";
});
```



### Установка политики кэширования



Если в приложении множество конечных точек, для которых надо применять одни и те же параметры кэширования, то лучше подобные параметры выделить в отдельную политику. При этом мы можем настроить одну базовую политику, которая будет действовать глобально и задать отдельные именованные политики, которые будут применяться при необходимости. Для этого в метод **AddOutputCache()** передается делегат `Action `. Объект OutputCacheOptions имеет два метода: `AddBasePolicy()` (настраивает базовую политику) и `AddPolicy` (настраивает именованную политику). Все эти методы в качестве параметра принимают делегат с параметром **OutputCachePolicyBuilder**, методы которого выше уже были рассмотрены.



#### Настройка базовой политики



По умолчанию в приложении уже определена базовая политика кэширования, которая предусматривает, что





- Кэшируются только ответы со статусным кодом 200

- Кэшируются только ответы на запросы типа GET и HEAD

- Если в ответе устанавливаются куки, то ответ не кэшируется

- Ответы на аутентифицированные запросы не кэшируются



Настроим базовую политику, например, установим время кэширования в 1 минуту:



```c#

var users = new List<string> { "Tom", "Bob", "Sam" }; 

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOutputCache(options =>
{
    options.AddBasePolicy(builder => builder.Expire(TimeSpan.FromMinutes(1)));
});

var app = builder.Build();

app.UseOutputCache();

app.MapGet("/", () => users).CacheOutput();

app.Run();
```



#### Именованные политики



Наряду с базовой политикой можно определить и именнованные политики:



```c#

var users = new List<string> { "Tom", "Bob", "Sam" }; 

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOutputCache(options =>
{
    options.AddBasePolicy(builder => builder.Expire(TimeSpan.FromMinutes(1)));
    options.AddPolicy("Expire2", builder => builder.Expire(TimeSpan.FromMinutes(2)));
    options.AddPolicy("Expire3", builder =>builder.Expire(TimeSpan.FromMinutes(3)));
});

var app = builder.Build();

app.UseOutputCache();
app.MapGet("/", () => users).CacheOutput("Expire2");    // применяем политику "Expire2"

app.Run();
```



Здесь определены две именнованные политики - "Expire2" и "Expire3", которые устанавливают время действия кэша в 2 и 3 секунду соответственно. Для применения именованной политики можно использовать специальную перегрузку метода **CacheOutput()**, которая принимает имя политики. В этом случае именованная политика переопределяет действие базовой.



Также можно установить нужную политику при использовании атрибута OutputCache. Для этого у атрибута есть свойство **PolicyName**, которое принимает имя политики:



```c#
app.MapGet("/", [OutputCache(PolicyName ="Expire2")] () => users);
```

Любое приложение не защищено от ошибок и снижения работоспособности в силу ряда причин, некоторые из которых трудно спрогнозировать на этапе разработки. И соответственно возникает вопрос мониторинга рабоспособности приложения. Фреймворк ASP.NET Core предоставляет специальный компонент middleware для отслеживания работоспособности приложения. С помощью данного middleware мы можем настроить проверку различных метрик и показателей, которые нам важны в рамках конкретного приложения. Например, можно проверять доступность какого-то сетевого сервиса, базы данных, использование физических ресурсов сервера (памяти, диска и т.д.)



### Добавление Health Checks Middleware



Для добавления функционала проверки работоспособности прежде всего необходимо добавить в коллекцию сервисов приложения сервис HealthCheckService с помощью метода **AddHealthChecks()**



```c#
builder.Services.AddHealthChecks();
```



Проверка работоспособности доступна через специальные конечные точки. Для задания конечной точки применяются два метода:



```c#
app.UseHealthChecks("/health");
```



и



```c#
app.MapHealthChecks("/health");
```



В реальности разница между этими не большая. Первый метод принимает, как минимум, строку пути, запрос по которому будет обрабатываться. Второй метод принимает шаблон пути. В случаях выше оба метода позволяют обрабатывать запросы по пути "/health"



### Пример применения Health Check Middleware



Рассмотрим небольшой пример, где имитириуется применение этой функционость. Допустим, наше приложение разделено на два слоя. Первый слой (первое приложение) генерирует некоторые данные, а второй слой (второе приложение) получает данные и непосредственно взаимодействует с клиентом.



В первом проекте, который будет отвечать за генерацию данных (допустим, он будет называться **DataApp**) определим следующий код:



```c#

var builder = WebApplication.CreateBuilder(args);
builder.WebHost.UseUrls("https://[::]:33333");

var app = builder.Build();

app.MapGet("/reset", () =>
{
    Latency.ResetLatency();
    return "Application reset";
});
app.MapGet("/data", async () =>
{
    int latency = Latency.GetLatency();
    await Task.Delay(latency);
    return $"Application latency: {latency}";
});

app.Run();

static class Latency
{
    static int counter = 1;
    // увеличиваем счетчик
    public static int GetLatency() => counter++ * 500;
    // сбрасываем счетчик
    public static void ResetLatency() => counter = 1;
}
```



Это приложение будет имитировать латентность или задержки при получении и обработке запросов. Для этого определяем вспомогательный статический класс Latency. Его метод `GetLatency()` увеличивает счетчик и возвращает значение `counter++ * 500`. Метод `ResetLatency()` сбрасывает значение счетчика к начальному.



Для простоты данное приложение будет запускаться по адресу `https://localhost:33333`.



Приложение определяет две конечные точки. Конечная точка `app.MapGet("/reset"...` обрабатывает запросы по пути "reset" и условно осуществляет восстановление сервера (по сути сбрасывает значение счетчика к начальному).



Вторая конечная точка - `app.MapGet("/data"...` собственно посылает данные. Но для имитации все повыщаеющеся латентности приложения ее обработчик получает новое значение из метода `Latency.GetLatency()`, осуществляет задержку и отправляет ответ.



```c#

int latency = Latency.GetLatency();
await Task.Delay(latency);
return $"Application latency: {latency}";
```



То есть таким образом, мы имитируем повышение латентности с каждым новым запросом. Соответственно с каждым новым запросом при вызове метода `Latency.GetLatency()` будет все больше увеличиваться значение счетчика и будет возвращаться все большее значение. И сервер будет все медленнее и медленнее обрабатывать запросы.






Теперь определим второй проект ASP.NET Core, который будет обращаться к предыдущему приложению DataApp и проверять его работоспособность:



```c#

using Microsoft.Extensions.Diagnostics.HealthChecks;
using System.Diagnostics;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddHealthChecks()
    .AddCheck<RequestTimeHealthCheck>("RequestTimeCheck");  // проверяем работоспособность с RequestTimeCheck

builder.Services.AddHttpClient();   // подключаем HttpClient
builder.WebHost.UseUrls("https://[::]:44444");  // обрабатываем запросы по адресу https://localhost:44444

var app = builder.Build();
app.MapHealthChecks("/health");

app.MapGet("/", async (HttpClient httpClient) =>
{
    // отправляем запрос к другому сервису и возвращаем его ответ
    var response = await httpClient.GetAsync("https://localhost:33333/data");
    return await response.Content.ReadAsStringAsync();
});

app.Run();

public class RequestTimeHealthCheck : IHealthCheck
{
    int degraded_level = 2000;  // уровень плохой работы
    int unhealthy_level = 5000; // нерабочий уровень
    HttpClient httpClient;
    public RequestTimeHealthCheck(HttpClient client) => httpClient = client;
    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, 
        CancellationToken cancellationToken = default)
    {
        // получаем время запроса
        Stopwatch sw = Stopwatch.StartNew();
        await httpClient.GetAsync("https://localhost:33333/data");
        sw.Stop();
        var responseTime = sw.ElapsedMilliseconds;
        // в зависимости от времени запроса возвращаем определенный результат
        if (responseTime < degraded_level)
        {
            return HealthCheckResult.Healthy("Система функционирует хорошо");
        }
        else if (responseTime < unhealthy_level)
        {
            return HealthCheckResult.Degraded("Снижение качества работы системы");
        }
        else
        {
            return HealthCheckResult.Unhealthy("Система в нерабочем состоянии. Необходим ее перезапуск.");
        }
    }
}
```



Здесь прежде всего подключаем сервис проверки работоспособности:



```c#
builder.Services.AddHealthChecks()
```



Этот метод возвращает объект `IHealthCheckBuilder`, который применяется для создания и настройки сервиса HealthCheckService. Но сама проверка работоспособоности применяется объект IHealthCheck. И для добавления такого объекта применяется метод **AddCheck()**:



```c#
.AddCheck<RequestTimeHealthCheck>("RequestTimeCheck");
```



Этот метод типизируется типом, который реализует интерфейс IHealthCheck, а в качества параметра принимает строку - имя для сервиса проверки.



В нашем случае в качестве реализации IHealthCheck применяется класс RequestTimeCheck. Класс должен реализовать метод интерфейса **CheckHealthAsync**. В примере выше в этом методе отправляем запрос к первому приложению к его конечной точке "/data" и проверяем время запроса:



```c#

Stopwatch sw = Stopwatch.StartNew();
await httpClient.GetAsync("https://localhost:33333/data");
sw.Stop();
var responseTime = sw.ElapsedMilliseconds;
```



Если время запроса превосходит определенные предустоновленые пределы, то возвращает соответствующее сообщение о работоспособности приложения:



```c#

 if (responseTime < degraded_level)
{
    return HealthCheckResult.Healthy("Система функционирует хорошо");
}
else if (responseTime < unhealthy_level)
{
    return HealthCheckResult.Degraded("Снижение качества работы системы");
}
else
{
    return HealthCheckResult.Unhealthy("Система в нерабочем состоянии. Необходим ее перезапуск.");
}
```



Метод возвращает результат проверки работоспособности - структура HealthCheckResult. Конкретный результат устанавливается с помощью одного из методов структуры: `Healthy()` (приложение работает нормально), `Degraded()` (работоспособность снижается) и `Unhealthy()` (приложение неработоспособно). Каждый метод возвращает соответствующий экземпляр структуры, который сигнализирует о состоянии приложения.



Когда, при каких условиях считать приложение неработоспособным - это зависит от нашей задачи, логики нашего приложения, метрик, которые мы применяем для оценки и конкретной ситуации. В данном случае все зависит от времени запроса.



Для получения информации о работоспособности приложении определена конечная точка "/health" посредством метода



```c#
app.MapHealthChecks("/health");
```



![health check middleware в приложении на asp.net core и c#](/uploads/course-lectures/d1d4775d347131663f560e2f3b0123621a311e63.png)



Запустим сначала приложение DataApp, а затем AggregationApp. Обратимся в браузере по адресу "https://localhost:44444/" (то есть к AggregationApp):



![проверка работоспособности приложения на asp.net core и c#](/uploads/course-lectures/0f762b3f08cd39436ae762b85da3f3bf14a675ae.png)



В данном случае AggregationApp будет обращаться по адресу "https://localhost:33333/data" к DataApp и получает данные. Но внутри DataApp это приведет к увеличению задержки при обработки запроса. И каждый последующий запрос будет обрабатываться все медленнее и медленнее.



Если после 5 запросов мы обратимся в браузере по адресу "https://localhost:44444/health", то консоль браузера выведет предупреждение о снижении работоспособности



